export function MexicoMap({ label, tone = "dark", className = "w-full" }: MexicoMapProps) {
  const colors = TONES[tone];

  return (
    <svg viewBox="0 0 420 269" role="img" aria-label={label} className={className}>
      <g fill={colors.states} stroke={colors.stroke} strokeWidth="0.8" strokeLinejoin="round" fillRule="evenodd">
        {STATES.map((state, index) => (
          <path key={index} d={state} />
        ))}
      </g>
      <path d={PUEBLA} fill={colors.puebla} stroke={colors.pueblaStroke} strokeWidth={tone === "light" ? 1.2 : 1.4} strokeLinejoin="round" />
    </svg>
  );
}
